<!doctype html>
<html lang="en-CA">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<title>Even Keel · Split trip costs fairly</title>
<meta name="description" content="Log who paid for what on your trip and see who owes whom, so everyone ends up even.">
<meta name="theme-color" content="#1F3A4D">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48'%3E%3Crect width='48' height='48' rx='11' fill='%231F3A4D'/%3E%3Cpath d='M8 17H40L36.2 26.4Q35.1 29 32.3 29H15.7Q12.9 29 11.8 26.4Z' fill='%23F4F1EA'/%3E%3Cpath d='M10.43 23H37.57L36.52 25.6H11.48Z' fill='%23C2462B'/%3E%3Cpath d='M21.5 29h5l-.9 8h-3.2z' fill='%23F4F1EA'/%3E%3C/svg%3E">
<link rel="preconnect" href="https://fonts.googleapis.com">
