<div id="live" class="vh" aria-live="polite" aria-atomic="true"></div>

<script>
(() => {
  'use strict';

  const STORAGE_KEY = 'even-keel/trip/v1';
  const money = new Intl.NumberFormat('en-CA', { style: 'currency', currency: 'CAD' });
  const fmt = (cents) => money.format(cents / 100);
  const listFormat = typeof Intl.ListFormat === 'function'
    ? new Intl.ListFormat('en-CA', { style: 'long', type: 'conjunction' })
    : null;
  const joinNames = (names) => (listFormat ? listFormat.format(names) : names.join(', '));
  const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
  const keyOf = (name) => name.normalize('NFC').toLowerCase();
  const AVATAR_COLOURS = ['#1F3A4D', '#2C6468', '#8A5A1E', '#4F5B8C', '#4E6B3A', '#7A3E5C'];

  const $ = (id) => document.getElementById(id);
  const els = {
    tripTotal: $('trip-total'),
    tripMeta: $('trip-meta'),
    personForm: $('person-form'),
    personName: $('person-name'),
    peopleList: $('people-list'),
    peopleEmpty: $('people-empty'),
    peopleCount: $('people-count'),
    expenseForm: $('expense-form'),
    desc: $('expense-desc'),
    amount: $('expense-amount'),
    payer: $('expense-payer'),
    split: $('expense-split'),
    splitTools: $('split-tools'),
    splitAll: $('split-all'),
    splitNone: $('split-none'),
    splitPreview: $('split-preview'),
    expenseStatus: $('expense-status'),
    balanceList: $('balance-list'),
    balancesEmpty: $('balances-empty'),
    balanceCheck: $('balance-check'),
    transferList: $('transfer-list'),
    settleEmpty: $('settle-empty'),
    settleFoot: $('settle-foot'),
    settleSummary: $('settle-summary'),
    copySettle: $('copy-settle'),
    copyStatus: $('copy-status'),
    expensesTitle: $('expenses-title'),
    expenseCount: $('expense-count'),
    expenseList: $('expense-list'),
    expensesEmpty: $('expenses-empty'),
    undoNotice: $('undo-notice'),
    undoText: $('undo-text'),
    undoBtn: $('undo-btn'),
    saveNote: $('save-note'),
    reset: $('reset-trip'),
    live: $('live')
  };

  const errorSlots = {
    person: $('person-error'),
    desc: $('desc-error'),
    amount: $('amount-error'),
    payer: $('payer-error'),
    split: $('split-error'),
    expense: $('expense-error')
  };
  const errorFields = {
    person: els.personName,
    desc: els.desc,
    amount: els.amount,
    payer: els.payer,
    split: null,
    expense: null
  };

  /* ---------- State ---------- */
  let storageWorks = true;
  let state = load();
  let lastRemoved = null;
  let payerChoice = '';
  let renderedPeopleKey = null;
  const splitChecked = new Map(state.people.map((n) => [n, true]));

  function emptyTrip() { return { people: [], expenses: [] }; }

  function makeId() {
    return 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function load() {
    let raw = null;
    try { raw = window.localStorage.getItem(STORAGE_KEY); }
    catch (err) { storageWorks = false; return emptyTrip(); }
    if (!raw) return emptyTrip();
    try { return sanitize(JSON.parse(raw)); }
    catch (err) { return emptyTrip(); }
  }

  function sanitize(data) {
    const people = [];
    const seen = new Set();
    if (data && Array.isArray(data.people)) {
      for (const p of data.people) {
        if (typeof p !== 'string') continue;
        const name = p.trim();
        if (!name || seen.has(keyOf(name))) continue;
        seen.add(keyOf(name));
        people.push(name);
      }
    }
    const known = new Set(people);
    const expenses = [];
    if (data && Array.isArray(data.expenses)) {
      for (const e of data.expenses) {
        if (!e || typeof e !== 'object') continue;
        const description = typeof e.description === 'string' ? e.description.trim() : '';
        if (!description || !Number.isSafeInteger(e.cents) || e.cents <= 0) continue;
        if (!known.has(e.payer)) continue;
        const split = Array.isArray(e.split) ? people.filter((n) => e.split.includes(n)) : [];
        if (!split.length) continue;
        expenses.push({
          id: typeof e.id === 'string' && e.id ? e.id : makeId(),
          description,
          cents: e.cents,
          payer: e.payer,
          split
        });
      }
    }
    return { people, expenses };
  }

  function save() {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      storageWorks = true;
    } catch (err) {
      storageWorks = false;
    }
    setSaveNote();
  }

  function setSaveNote() {
    els.saveNote.textContent = storageWorks
      ? 'Saved in this browser on this device. Nothing is sent anywhere.'
      : 'This browser isn’t letting Even Keel save, so a reload will clear the trip. Private browsing can cause this.';
    els.saveNote.classList.toggle('save-warn', !storageWorks);
  }

  /* ---------- Money logic (integer cents) ---------- */
  function sharesFor(expense) {
    const members = state.people.filter((n) => expense.split.includes(n));
    const shares = new Map();
    const count = members.length;
    if (!count) return shares;
    const base = Math.floor(expense.cents / count);
    const extra = expense.cents - base * count;
    members.forEach((name, i) => shares.set(name, base + (i < extra ? 1 : 0)));
    return shares;
  }

  function computeBalances() {
    const rows = state.people.map((name) => ({ name, paid: 0, share: 0, net: 0 }));
    const byName = new Map(rows.map((r) => [r.name, r]));
    for (const e of state.expenses) {
      const payer = byName.get(e.payer);
      if (payer) payer.paid += e.cents;
      for (const [name, cents] of sharesFor(e)) {
        const row = byName.get(name);
        if (row) row.share += cents;
      }
    }
    for (const r of rows) r.net = r.paid - r.share;
    return rows;
  }

  // Greedy matching: each step settles at least one person fully,
  // so it never needs more than (non-zero balances − 1) transfers.
  function computeTransfers(rows) {
    const creditors = [];
    const debtors = [];
    rows.forEach((r, idx) => {
      if (r.net > 0) creditors.push({ name: r.name, amt: r.net, idx });
      else if (r.net < 0) debtors.push({ name: r.name, amt: -r.net, idx });
    });
    const byLargest = (a, b) => (b.amt - a.amt) || (a.idx - b.idx);
    const transfers = [];
    while (creditors.length && debtors.length) {
      creditors.sort(byLargest);
      debtors.sort(byLargest);
      const c = creditors[0];
      const d = debtors[0];
      const cents = Math.min(c.amt, d.amt);
      transfers.push({ from: d.name, to: c.name, cents });
      c.amt -= cents;
      d.amt -= cents;
      if (c.amt === 0) creditors.shift();
      if (d.amt === 0) debtors.shift();
    }
    return transfers;
  }

  function parseAmount(raw) {
    let s = String(raw == null ? '' : raw).trim().replace(/\s+/g, '');
    let negative = false;
    if (/^[-\u2212]/.test(s)) { negative = true; s = s.slice(1); }
    s = s.replace(/^(?:CA)?\$/i, '');
    if (!negative && /^[-\u2212]/.test(s)) { negative = true; s = s.slice(1); }
    if (!s) {
      return { error: negative ? 'Enter an amount greater than $0.00.' : 'Enter how much it cost, like 42 or 42.50.' };
    }
    if (s.includes(',')) {
      if (/^\d{1,3}(,\d{3})+(\.\d*)?$/.test(s)) s = s.replace(/,/g, '');
      else return { error: 'Use a dot for cents and commas only between thousands, like 1,234.50.' };
    }
    const m = /^(\d*)(?:\.(\d*))?$/.exec(s);
    if (!m || (!m[1] && !m[2])) return { error: 'Enter the amount as a number, like 42 or 42.50.' };
    const frac = m[2] || '';
    if (frac.length > 2) return { error: 'Amounts go to the cent. Use at most 2 decimal places, like 12.75.' };
    if (negative) return { error: 'Enter an amount greater than $0.00.' };
    const whole = (m[1] || '0').replace(/^0+(?=\d)/, '');
    if (whole.length > 9) return { error: 'That’s more than Even Keel can track. Keep amounts under $1,000,000,000.' };
    const cents = Number(whole) * 100 + Number((frac + '00').slice(0, 2));
    if (cents <= 0) return { error: 'Enter an amount greater than $0.00.' };
    return { cents };
  }

  /* ---------- DOM helpers ---------- */
  function h(tag, props, ...children) {
    const node = document.createElement(tag);
    if (props) {
      for (const key of Object.keys(props)) {
        const value = props[key];
        if (value === null || value === undefined || value === false) continue;
        if (key === 'class') node.className = value;
        else node.setAttribute(key, value === true ? '' : String(value));
      }
    }
    appendAll(node, children);
    return node;
  }
  function appendAll(node, children) {
    for (const child of children) {
      if (child === null || child === undefined || child === false) continue;
      if (Array.isArray(child)) appendAll(node, child);
      else node.append(child instanceof Node ? child : document.createTextNode(String(child)));
    }
  }

  function avatar(name, small) {
    const idx = state.people.indexOf(name);
    const colour = AVATAR_COLOURS[(idx < 0 ? 0 : idx) % AVATAR_COLOURS.length];
    const initial = (Array.from(name.trim())[0] || '?').toUpperCase();
    return h('span', {
      class: small ? 'avatar avatar-sm' : 'avatar',
      'aria-hidden': 'true',
      'data-initial': initial,
      style: `--c:${colour}`
    });
  }

  function arrowIcon() {
    const ns = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(ns, 'svg');
    svg.setAttribute('viewBox', '0 0 20 20');
    svg.setAttribute('aria-hidden', 'true');
    svg.setAttribute('focusable', 'false');
    const path = document.createElementNS(ns, 'path');
    path.setAttribute('d', 'M3 10h13M11 5l5 5-5 5');
    path.setAttribute('fill', 'none');
    path.setAttribute('stroke', 'currentColor');
    path.setAttribute('stroke-width', '2');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('stroke-linejoin', 'round');
    svg.append(path);
    return svg;
  }

  function setEmpty(el, title, body, even) {
    el.replaceChildren(
      h('strong', { class: 'empty-title' }, title),
      body ? h('span', null, body) : null
    );
    el.classList.toggle('is-even', !!even);
  }

  function setStatus(el, message) {
    if (!message) { el.replaceChildren(); return; }
    el.replaceChildren(h('span', { class: 'ok-icon', 'aria-hidden': 'true' }), h('span', null, message));
  }

  let announceTimer = null;
  function announce(message) {
    clearTimeout(announceTimer);
    els.live.textContent = '';
    announceTimer = setTimeout(() => { els.live.textContent = message; }, 80);
  }

  /* ---------- Validation messages ---------- */
  function clearError(key) {
    const slot = errorSlots[key];
    slot.hidden = true;
    slot.removeAttribute('data-testid');
    slot.querySelector('.err-text').textContent = '';
    const field = errorFields[key];
    if (field) field.removeAttribute('aria-invalid');
  }
  function clearErrors() {
    for (const key of Object.keys(errorSlots)) clearError(key);
  }
  function showError(key, message, focusTarget) {
    clearErrors();
    setStatus(els.expenseStatus, '');
    const slot = errorSlots[key];
    slot.querySelector('.err-text').textContent = message;
    slot.hidden = false;
    slot.setAttribute('data-testid', 'form-error');
    const field = errorFields[key];
    if (field) field.setAttribute('aria-invalid', 'true');
    const target = focusTarget === undefined ? field : focusTarget;
    if (target && document.activeElement !== target) target.focus();
    announce(message);
  }

  /* ---------- Rendering ---------- */
  function render() {
    renderTotals();
    renderPeople();
    renderFormOptions();
    const rows = computeBalances();
    renderBalances(rows);
    renderSettle(rows);
    renderExpenses();
    renderUndo();
  }

  function commit() {
    save();
    render();
  }

  function renderTotals() {
    const total = state.expenses.reduce((sum, e) => sum + e.cents, 0);
    els.tripTotal.textContent = fmt(total);
    if (!state.people.length && !state.expenses.length) {
      els.tripMeta.textContent = 'Nothing logged yet';
    } else {
      els.tripMeta.textContent = `${plural(state.expenses.length, 'expense', 'expenses')} · ${plural(state.people.length, 'person', 'people')}`;
    }
  }

  function renderPeople() {
    const count = state.people.length;
    els.peopleCount.textContent = plural(count, 'person', 'people');
    els.peopleCount.hidden = count === 0;
    els.peopleList.hidden = count === 0;
    els.peopleEmpty.hidden = count > 0;
    els.peopleList.replaceChildren(...state.people.map((name) =>
      h('li', { class: 'person', 'data-testid': 'person' },
        avatar(name),
        h('span', { class: 'person-name' }, name)
      )
    ));
  }

  function renderFormOptions() {
    const key = state.people.join('\u0001');
    if (!state.people.includes(payerChoice)) payerChoice = state.people[0] || '';

    if (key !== renderedPeopleKey) {
      renderedPeopleKey = key;
      if (state.people.length) {
        els.payer.replaceChildren(...state.people.map((name) => h('option', { value: name }, name)));
        els.split.replaceChildren(...state.people.map((name) => {
          if (!splitChecked.has(name)) splitChecked.set(name, true);
          const input = h('input', { type: 'checkbox', value: name, name: 'split' });
          input.checked = !!splitChecked.get(name);
          return h('label', { class: 'chip' }, input, h('span', { class: 'chip-name' }, name));
        }));
      } else {
        els.payer.replaceChildren(h('option', { value: '' }, 'Add people first'));
        els.split.replaceChildren(h('p', { class: 'split-empty' }, 'Add people to the trip first, then choose who shares each cost.'));
      }
    } else {
      els.split.querySelectorAll('input[type="checkbox"]').forEach((input) => {
        input.checked = !!splitChecked.get(input.value);
      });
    }
    els.payer.value = payerChoice;
    els.splitTools.hidden = state.people.length === 0;
    updatePreview();
  }

  function checkedMembers() {
    const picked = new Set(
      Array.from(els.split.querySelectorAll('input[type="checkbox"]'))
        .filter((i) => i.checked)
        .map((i) => i.value)
    );
    return state.people.filter((n) => picked.has(n));
  }

  function updatePreview() {
    const p = els.splitPreview;
    if (!state.people.length) { p.replaceChildren(); p.hidden = true; return; }
    p.hidden = false;

    const members = checkedMembers();
    if (!members.length) {
      p.replaceChildren('Choose at least one person to share this cost.');
      return;
    }
    const who = members.length === state.people.length && members.length > 1
      ? `everyone (${members.length})`
      : members.length === 1 ? members[0] : plural(members.length, 'person', 'people');

    const parsed = parseAmount(els.amount.value);
    if (!els.amount.value.trim() || parsed.error) {
      p.replaceChildren(`Splitting between ${who}. Enter an amount to see each share.`);
      return;
    }
    const n = members.length;
    const cents = parsed.cents;
    if (n === 1) {
      p.replaceChildren(`${members[0]} covers the full `, h('strong', null, fmt(cents)), '.');
      return;
    }
    const base = Math.floor(cents / n);
    const extra = cents - base * n;
    if (!extra) {
      p.replaceChildren(h('strong', null, fmt(base)), ` each for ${n} people.`);
      return;
    }
    const first = members.slice(0, extra);
    const rest = members.slice(extra);
    p.replaceChildren(
      h('strong', null, fmt(base + 1)), `${first.length > 1 ? ' each' : ''} for ${joinNames(first)}, `,
      h('strong', null, fmt(base)), `${rest.length > 1 ? ' each' : ''} for ${joinNames(rest)}. `,
      'The extra cents go to whoever joined the trip first.'
    );
  }

  function renderBalances(rows) {
    if (!state.people.length) {
      els.balanceList.replaceChildren();
      els.balanceList.hidden = true;
      els.balanceCheck.hidden = true;
      setEmpty(els.balancesEmpty, 'No one to balance yet.', 'Add the people on your trip and their balances show up here.');
      els.balancesEmpty.hidden = false;
      return;
    }
    els.balancesEmpty.hidden = true;
    els.balanceList.hidden = false;

    const max = Math.max(1, ...rows.map((r) => Math.abs(r.net)));
    els.balanceList.replaceChildren(...rows.map((r) => {
      const net = r.net;
      const tone = net > 0 ? 'is-owed' : net < 0 ? 'owes' : 'square';
      const width = net === 0 ? 0 : Math.max(2, (Math.abs(net) / max) * 50);
      const amount = net === 0
        ? h('span', { class: 'balance-square' }, 'All square')
        : [
            h('span', { class: 'balance-label' }, net > 0 ? 'Is owed' : 'Owes'),
            ' ',
            h('span', { class: 'balance-value' }, fmt(Math.abs(net)))
          ];
      return h('li', {
          class: `balance ${tone}`,
          'data-testid': 'balance',
          'data-person': r.name,
          'data-cents': String(net)
        },
        h('div', { class: 'balance-who' },
          avatar(r.name),
          h('div', { class: 'balance-id' },
            h('span', { class: 'balance-name' }, r.name),
            ' ',
            h('span', { class: 'balance-detail' }, `Paid ${fmt(r.paid)} · Share ${fmt(r.share)}`)
          )
        ),
        ' ',
        h('div', { class: 'balance-amt' }, amount),
        h('div', { class: 'bar', 'aria-hidden': 'true' },
          net !== 0 ? h('span', { class: 'bar-fill', style: `width:${width.toFixed(2)}%` }) : null
        )
      );
    }));

    const owedTotal = rows.reduce((sum, r) => sum + (r.net > 0 ? r.net : 0), 0);
    if (!state.expenses.length) {
      els.balanceCheck.textContent = 'Log an expense to see balances move.';
      els.balanceCheck.hidden = false;
    } else if (owedTotal > 0) {
      els.balanceCheck.textContent = `Owed and owing both come to ${fmt(owedTotal)}, so it all evens out.`;
      els.balanceCheck.hidden = false;
    } else {
      els.balanceCheck.hidden = true;
    }
  }

  function renderSettle(rows) {
    const transfers = computeTransfers(rows);
    els.copyStatus.replaceChildren();
    if (!transfers.length) {
      els.transferList.replaceChildren();
      els.transferList.hidden = true;
      els.settleFoot.hidden = true;
      if (state.expenses.length) {
        setEmpty(els.settleEmpty, 'You’re all even.', 'Nobody needs to pay anybody right now.', true);
      } else {
        setEmpty(els.settleEmpty, 'Nothing to settle yet.', 'Once you log expenses, this shows who pays whom so everyone ends up even.');
      }
      els.settleEmpty.hidden = false;
      return;
    }
    els.settleEmpty.hidden = true;
    els.transferList.hidden = false;
    els.transferList.replaceChildren(...transfers.map((t) =>
      h('li', {
          class: 'transfer',
          'data-testid': 'transfer',
          'data-from': t.from,
          'data-to': t.to,
          'data-cents': String(t.cents)
        },
        h('span', { class: 't-party' }, avatar(t.from, true), h('span', { class: 't-name' }, t.from)),
        ' ',
        h('span', { class: 't-verb' }, 'pays', arrowIcon()),
        ' ',
        h('span', { class: 't-party' }, avatar(t.to, true), h('span', { class: 't-name' }, t.to)),
        ' ',
        h('span', { class: 't-amt' }, fmt(t.cents))
      )
    ));
    els.settleSummary.textContent = `${plural(transfers.length, 'payment', 'payments')} and everyone’s even.`;
    els.settleFoot.hidden = false;
  }

  function renderExpenses() {
    const count = state.expenses.length;
    els.expenseCount.textContent = plural(count, 'expense', 'expenses');
    els.expenseCount.hidden = count === 0;

    if (!count) {
      els.expenseList.replaceChildren();
      els.expenseList.hidden = true;
      if (state.people.length) {
        setEmpty(els.expensesEmpty, 'No expenses yet.', 'When someone pays for something the group shares, like gas, groceries or the cabin, log it and the balances update on their own.');
      } else {
        setEmpty(els.expensesEmpty, 'Nothing logged yet.', 'Add the people on your trip, then log what each of them paid.');
      }
      els.expensesEmpty.hidden = false;
      return;
    }
    els.expensesEmpty.hidden = true;
    els.expenseList.hidden = false;

    els.expenseList.replaceChildren(...state.expenses.slice().reverse().map((e) => {
      const members = state.people.filter((n) => e.split.includes(n));
      const n = members.length || 1;
      const base = Math.floor(e.cents / n);
      const extra = e.cents - base * n;
      let shares;
      if (members.length === 1) {
        shares = `Just for ${members[0]}`;
      } else {
        const each = extra ? `${fmt(base)}–${fmt(base + 1)} each` : `${fmt(base)} each`;
        shares = `Split between ${joinNames(members)} · ${each}`;
      }
      return h('li', { class: 'expense', 'data-testid': 'expense', 'data-id': e.id },
        h('h3', { class: 'expense-desc' }, e.description),
        ' ',
        h('p', { class: 'expense-amt' }, fmt(e.cents)),
        h('p', { class: 'expense-paid' },
          'Paid by ',
          h('span', { class: 'payer' }, avatar(e.payer, true), h('strong', null, e.payer))
        ),
        h('p', { class: 'expense-shares' }, shares),
        h('div', { class: 'expense-actions' },
          h('button', {
              type: 'button',
              class: 'btn btn-quiet btn-sm',
              'data-testid': 'delete-expense',
              'data-id': e.id
            },
            'Remove',
            h('span', { class: 'vh' }, ` ${e.description}, ${fmt(e.cents)}`)
          )
        )
      );
    }));
  }

  function renderUndo() {
    if (!lastRemoved) { els.undoNotice.hidden = true; return; }
    const e = lastRemoved.expense;
    els.undoText.textContent = `Removed “${e.description}” (${fmt(e.cents)}).`;
    els.undoNotice.hidden = false;
  }

  /* ---------- Actions ---------- */
  els.personForm.addEventListener('submit', (ev) => {
    ev.preventDefault();
    const name = els.personName.value.trim();
    if (!name) {
      showError('person', 'Enter a name to add someone to the trip.');
      return;
    }
    const existing = state.people.find((p) => keyOf(p) === keyOf(name));
    if (existing) {
      showError('person', `${existing} is already on the trip. If this is someone else, add a last initial, like “${name} B.”`);
      return;
    }
    clearErrors();
    state.people.push(name);
    splitChecked.set(name, true);
    els.personName.value = '';
    commit();
    els.personName.focus();
    announce(`${name} added. ${plural(state.people.length, 'person', 'people')} on the trip.`);
  });

  els.personName.addEventListener('input', () => {
    if (!errorSlots.person.hidden) clearError('person');
  });

  els.expenseForm.addEventListener('submit', (ev) => {
    ev.preventDefault();
    if (!state.people.length) {
      showError('expense', 'Add at least one person to the trip before logging an expense. Start with the Name field above.', null);
      return;
    }
    const description = els.desc.value.trim();
    if (!description) {
      showError('desc', 'Add a short description so everyone knows what this was for.');
      return;
    }
    const parsed = parseAmount(els.amount.value);
    if (parsed.error) {
      showError('amount', parsed.error);
      return;
    }
    const payer = els.payer.value;
    if (!state.people.includes(payer)) {
      showError('payer', 'Choose who paid.');
      return;
    }
    const split = checkedMembers();
    if (!split.length) {
      showError('split', 'Choose at least one person to split this between.', els.split.querySelector('input[type="checkbox"]'));
      return;
    }

    clearErrors();
    state.expenses.push({ id: makeId(), description, cents: parsed.cents, payer, split });
    lastRemoved = null;
    payerChoice = payer;
    state.people.forEach((n) => splitChecked.set(n, true));
    els.desc.value = '';
    els.amount.value = '';
    commit();
    els.desc.focus();
    setStatus(els.expenseStatus, `Added “${description}” · ${fmt(parsed.cents)}, paid by ${payer}.`);
  });

  els.desc.addEventListener('input', () => {
    if (!errorSlots.desc.hidden) clearError('desc');
  });
  els.amount.addEventListener('input', () => {
    if (!errorSlots.amount.hidden) clearError('amount');
    updatePreview();
  });
  els.payer.addEventListener('change', () => {
    payerChoice = els.payer.value;
    if (!errorSlots.payer.hidden) clearError('payer');
  });
  els.split.addEventListener('change', (ev) => {
    const input = ev.target;
    if (!(input instanceof HTMLInputElement) || input.type !== 'checkbox') return;
    splitChecked.set(input.value, input.checked);
    if (!errorSlots.split.hidden) clearError('split');
    updatePreview();
  });

  function setAllSplit(checked) {
    els.split.querySelectorAll('input[type="checkbox"]').forEach((input) => {
      input.checked = checked;
      splitChecked.set(input.value, checked);
    });
    if (checked && !errorSlots.split.hidden) clearError('split');
    updatePreview();
  }
  els.splitAll.addEventListener('click', () => setAllSplit(true));
  els.splitNone.addEventListener('click', () => setAllSplit(false));

  els.expenseList.addEventListener('click', (ev) => {
    const btn = ev.target instanceof Element ? ev.target.closest('[data-testid="delete-expense"]') : null;
    if (!btn) return;
    removeExpense(btn.getAttribute('data-id'));
  });

  function removeExpense(id) {
    const index = state.expenses.findIndex((e) => e.id === id);
    if (index < 0) return;
    const shownAt = state.expenses.length - 1 - index;
    const [removed] = state.expenses.splice(index, 1);
    lastRemoved = { expense: removed, index };
    commit();
    const buttons = els.expenseList.querySelectorAll('[data-testid="delete-expense"]');
    const next = buttons[Math.min(shownAt, buttons.length - 1)];
    if (next) next.focus();
    else els.undoBtn.focus();
    announce(`Removed ${removed.description}. Use Undo to bring it back.`);
  }

  els.undoBtn.addEventListener('click', () => {
    if (!lastRemoved) return;
    const { expense, index } = lastRemoved;
    lastRemoved = null;
    const stillValid = state.people.includes(expense.payer) && expense.split.some((n) => state.people.includes(n));
    if (!stillValid) {
      render();
      els.expensesTitle.focus();
      announce('That expense can’t come back because its people are no longer on the trip.');
      return;
    }
    state.expenses.splice(Math.min(index, state.expenses.length), 0, expense);
    commit();
    const restored = els.expenseList.querySelector(`[data-testid="delete-expense"][data-id="${CSS.escape(expense.id)}"]`);
    if (restored) restored.focus();
    else els.expensesTitle.focus();
    announce(`Brought back ${expense.description}.`);
  });

  els.copySettle.addEventListener('click', async () => {
    const transfers = computeTransfers(computeBalances());
    if (!transfers.length) return;
    const text = ['Even Keel · settle up', ...transfers.map((t) => `${t.from} pays ${t.to} ${fmt(t.cents)}`)].join('\n');
    let copied = false;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
        copied = true;
      }
    } catch (err) {
      copied = false;
    }
    if (!copied) {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.top = '-1000px';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try { copied = document.execCommand('copy'); } catch (err) { copied = false; }
      ta.remove();
      els.copySettle.focus();
    }
    setStatus(els.copyStatus, copied
      ? 'Copied. Paste it into your group chat.'
      : 'Couldn’t copy automatically. Select the list above and copy it yourself.');
  });

  els.reset.addEventListener('click', () => {
    if (!state.people.length && !state.expenses.length) {
      announce('This trip is already empty.');
      return;
    }
    const ok = window.confirm('Start a new trip? This removes everyone and every expense saved in this browser.');
    if (!ok) return;
    state = emptyTrip();
    lastRemoved = null;
    payerChoice = '';
    splitChecked.clear();
    els.desc.value = '';
    els.amount.value = '';
    els.personName.value = '';
    clearErrors();
    setStatus(els.expenseStatus, '');
    commit();
    els.personName.focus();
    announce('New trip started. Add the people on this trip.');
  });

  window.addEventListener('storage', (ev) => {
    if (ev.key !== STORAGE_KEY) return;
    state = load();
    lastRemoved = null;
    for (const n of state.people) if (!splitChecked.has(n)) splitChecked.set(n, true);
    renderedPeopleKey = null;
    render();
  });

  setSaveNote();
  render();
})();
</script>
</body>
</html>
